replace_function('updateWaiting',r"""function updateWaiting(){const remaining=active().length-S.results.length;const message=app.querySelector('.focal .message');if(message)message.textContent=tr(remaining===1?'waitingLast':'waiting',{n:remaining});for(const p of active()){const cell=app.querySelector(`[data-player-slot="${p.id}"] .value`);if(!cell)continue;const done=S.results.some(r=>r.id===p.id);cell.innerHTML=done?ico('t'):t('counting');cell.setAttribute('aria-label',tr(done?'locked':'counting'));cell.classList.toggle('quiet',!done)}}""")
